    val xp = getStaticParams(ax)
    val yp = getStaticParams(ay)
    assert((xp intersect yp).isEmpty)

    // Create the ugly meet.
    val meet = insertStaticParams(makeIntersectionType(Set(clearStaticParams(ax), clearStaticParams(ay))),
                                  xp ++ yp)
